## Common Mistakes

1. **Using fast hash functions for passwords** — Using MD5, SHA-1, or SHA-256 for password storage. These are fast hash functions designed for integrity checking, not password storage. Attackers crack them at billions of attempts per second.

2. **Hardcoded encryption keys** — Storing encryption keys in source code, environment variables at build time, or configuration files committed to Git. Use dedicated secrets managers (AWS Secrets Manager, HashiCorp Vault).

3. **Rolling your own crypto** — Implementing custom encryption, token generation, or key derivation instead of using established libraries (bcrypt, argon2, libsodium). Custom crypto invariably contains flaws.

4. **Ignoring key rotation** — Never rotating encryption keys, API keys, or JWT signing secrets. If a key leaks, every historical encrypted value is compromised.

## Secure Implementation

### Tier 1: Critical Fix (5 minutes)

**Use bcrypt instead of crypto-js**

```javascript
// SECURE: Use bcrypt (industry standard)
const bcrypt = require('bcrypt');
const express = require('express');
const app = express();

const SALT_ROUNDS = 12;  // Cost factor (2^12 iterations)

app.post('/register', express.json(), (req, res) => {
    const { username, password } = req.body;

    // ✅ SECURE: bcrypt with 12 rounds
    // 12 rounds = ~330ms per hash on modern CPU
    // Automatically resistant to GPU attacks (not designed for GPUs)
    bcrypt.hash(password, SALT_ROUNDS, (err, hashedPassword) => {
        if (err) {
            return res.status(500).json({ error: 'Hash error' });
        }

        // Store securely (bcrypt includes salt in hash string)
        database.users.save({
            username: username,
            password: hashedPassword  // ✅ SECURE: bcrypt format with salt
        });

        res.json({ message: 'User registered' });
    });
});

app.post('/login', express.json(), (req, res) => {
    const { username, password } = req.body;

    const user = database.users.find(username);
    if (!user) return res.status(401).json({ error: 'Invalid credentials' });

    // ✅ SECURE: bcrypt compare (timing-safe)
    bcrypt.compare(password, user.password, (err, isMatch) => {
        if (err) {
            return res.status(500).json({ error: 'Comparison error' });
        }

        if (isMatch) {
            // Successful authentication
            const token = generateJWT(user);
            res.json({ message: 'Login successful', token: token });
        } else {
            // Failed authentication
            res.status(401).json({ error: 'Invalid credentials' });
        }
    });
});

// ✅ SECURE: Async/await version (more modern)
app.post('/register-async', express.json(), async (req, res) => {
    try {
        const { username, password } = req.body;

        // Validate password strength
        if (password.length < 12) {
            return res.status(400).json({ error: 'Password too short (min 12 chars)' });
        }

        const hashedPassword = await bcrypt.hash(password, SALT_ROUNDS);

        await database.users.save({
            username: username,
            password: hashedPassword,
            createdAt: new Date()
        });

        res.json({ message: 'User registered successfully' });
    } catch (err) {
        res.status(500).json({ error: 'Registration failed' });
    }
});
```

### Tier 2: Essential Defenses (15 minutes)

**Add Password Policy & Rate Limiting**

```javascript
// SECURE: Password strength requirements
const validator = require('validator');

function validatePassword(password) {
    // ✅ Enforce OWASP password policy
    const requirements = {
        minLength: password.length >= 12,
        hasUppercase: /[A-Z]/.test(password),
        hasLowercase: /[a-z]/.test(password),
        hasNumbers: /\d/.test(password),
        hasSpecial: /[!@#$%^&*]/.test(password),
        notCommon: !isCommonPassword(password),
        noUsername: password.toLowerCase() !== username.toLowerCase()
    };

    const passed = Object.values(requirements).every(r => r);
    return { passed, requirements };
}

app.post('/register', express.json(), async (req, res) => {
    const { username, password } = req.body;

    // ✅ Validate password strength
    const validation = validatePassword(password);
    if (!validation.passed) {
        return res.status(400).json({
            error: 'Password does not meet requirements',
            requirements: validation.requirements
        });
    }

    try {
        // ✅ Hash with bcrypt
        const hashedPassword = await bcrypt.hash(password, 12);

        await database.users.save({
            username: username,
            password: hashedPassword,
            passwordChangedAt: new Date(),
            loginAttempts: 0
        });

        res.json({ message: 'Registration successful' });
    } catch (err) {
        logger.error('Registration error:', err);
        res.status(500).json({ error: 'Registration failed' });
    }
});

// ✅ Rate limiting for login attempts
const rateLimit = require('express-rate-limit');

const loginLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,  // 15 minutes
    max: 5,                      // 5 attempts
    message: 'Too many login attempts, please try again later',
    skipSuccessfulRequests: true,
    keyGenerator: (req) => req.ip + req.body.username
});

app.post('/login', loginLimiter, express.json(), async (req, res) => {
    const { username, password } = req.body;

    try {
        const user = await database.users.findOne({ username });

        if (!user) {
            // ✅ Timing-safe: always hash input even if user not found
            await bcrypt.compare(password, '$2b$12$invalid.hash.to.prevent.timing.attack');
            return res.status(401).json({ error: 'Invalid credentials' });
        }

        const isMatch = await bcrypt.compare(password, user.password);

        if (isMatch) {
            // ✅ Reset login attempts on success
            await database.users.updateOne(
                { _id: user._id },
                { loginAttempts: 0, lastLogin: new Date() }
            );

            const token = generateJWT(user);
            res.json({ message: 'Login successful', token });
        } else {
            // ✅ Track failed attempts for security alerts
            await database.users.updateOne(
                { _id: user._id },
                { loginAttempts: user.loginAttempts + 1 }
            );

            if (user.loginAttempts >= 5) {
                // Lock account temporarily
                sendSecurityAlert(user.email, 'Suspicious login attempts');
            }

            res.status(401).json({ error: 'Invalid credentials' });
        }
    } catch (err) {
        logger.error('Login error:', err);
        res.status(500).json({ error: 'Login failed' });
    }
});
```

### Tier 3: Production Hardening (30 minutes)

**Add Monitoring, Auditing & Incident Response**

```javascript
// SECURE: Password change tracking and alerts
app.post('/change-password', async (req, res) => {
    const { oldPassword, newPassword } = req.body;
    const userId = req.user.id;  // From JWT

    try {
        const user = await database.users.findById(userId);

        // ✅ Verify old password
        const isMatch = await bcrypt.compare(oldPassword, user.password);
        if (!isMatch) {
            return res.status(401).json({ error: 'Current password incorrect' });
        }

        // ✅ Hash new password
        const hashedNewPassword = await bcrypt.hash(newPassword, 12);

        // ✅ Check that new password is different
        const isSamePassword = await bcrypt.compare(newPassword, user.password);
        if (isSamePassword) {
            return res.status(400).json({ error: 'Password must be different' });
        }

        // ✅ Store password change in audit log
        await database.auditLog.save({
            userId: userId,
            action: 'password_change',
            timestamp: new Date(),
            ipAddress: req.ip,
            userAgent: req.get('user-agent')
        });

        // ✅ Invalidate existing sessions (force re-login)
        await database.sessions.deleteMany({ userId: userId });

        // ✅ Send security notification
        sendEmail(user.email, {
            subject: 'Your password has been changed',
            body: 'If this was not you, please reset your password immediately.',
            actionUrl: 'https://app.example.com/security/reset'
        });

        // ✅ Log successful change
        logger.info(`Password changed for user: ${user.username}`);

        res.json({ message: 'Password changed successfully' });
    } catch (err) {
        logger.error('Password change error:', err);
        res.status(500).json({ error: 'Password change failed' });
    }
});

// ✅ Incident response for compromised passwords
app.post('/security/force-password-reset', async (req, res) => {
    // Admin endpoint for suspected compromise
    const { userIds } = req.body;

    try {
        // ✅ Invalidate all sessions for affected users
        await database.sessions.deleteMany({
            userId: { $in: userIds }
        });

        // ✅ Mark password as requiring reset
        await database.users.updateMany(
            { _id: { $in: userIds } },
            {
                passwordResetRequired: true,
                passwordResetToken: generateResetToken(),
                passwordResetExpires: new Date(Date.now() + 24*60*60*1000)  // 24 hours
            }
        );

        // ✅ Send force-reset emails
        for (const userId of userIds) {
            const user = await database.users.findById(userId);
            sendEmail(user.email, {
                subject: 'URGENT: Please reset your password',
                body: 'We detected suspicious activity. Please reset your password immediately.',
                actionUrl: `https://app.example.com/auth/reset/${user.passwordResetToken}`
            });
        }

        // ✅ Log incident
        logger.warn(`Force password reset initiated for ${userIds.length} users`);

        res.json({ message: `Password reset initiated for ${userIds.length} users` });
    } catch (err) {
        logger.error('Force password reset error:', err);
        res.status(500).json({ error: 'Operation failed' });
    }
});

// ✅ Integration tests
const assert = require('assert');

describe('Password Hashing Security', () => {
    it('should use bcrypt for password hashing', async () => {
        const password = 'TestPassword123!';
        const hashed = await bcrypt.hash(password, 12);

        // ✅ Verify hash is bcrypt format
        assert.match(hashed, /^\$2[aby]\$/);

        // ✅ Verify different hashes for same password (salt)
        const hashed2 = await bcrypt.hash(password, 12);
        assert.notEqual(hashed, hashed2);

        // ✅ Verify comparison works
        assert.ok(await bcrypt.compare(password, hashed));
    });

    it('should not store plaintext passwords', async () => {
        const user = await database.users.findOne({ username: 'testuser' });
        assert.notEqual(user.password, 'TestPassword123!');
    });

    it('should rate limit login attempts', async () => {
        // Make 6 login attempts
        for (let i = 0; i < 6; i++) {
            const res = await request(app)
                .post('/login')
                .send({ username: 'testuser', password: 'wrong' });

            if (i < 5) {
                assert.equal(res.status, 401);
            } else {
                // 6th attempt should be rate limited
                assert.equal(res.status, 429);
            }
        }
    });
});
```

## Summary

**The Core Issue:** crypto-js PBKDF2 defaults are fundamentally broken (1 iteration + SHA1). This is not a "misconfiguration" - it's the default behavior.

**The Simple Fix:** Use bcrypt instead. bcrypt is:
- Designed for password hashing (not generic crypto)
- Automatically handles salt generation
- Resistant to GPU/ASIC attacks (uses CPU-intensive algorithms)
- Industry standard (used by major platforms)

**Deployment Checklist:**
- ✅ Replace crypto-js with bcrypt (npm install bcrypt)
- ✅ Use 12+ rounds for bcrypt
- ✅ Add password strength validation
- ✅ Implement rate limiting on login
- ✅ Add audit logging for password changes
- ✅ Monitor for suspicious authentication patterns
- ✅ Prepare incident response for password compromise
